def topo_sort(graph):
    from collections import deque

    # Build in-degree map and include all nodes
    in_degree = {}
    all_nodes = set(graph.keys())
    for node, prereqs in graph.items():
        for p in prereqs:
            all_nodes.add(p)
            if p not in in_degree:
                in_degree[p] = 0

    # Ensure every node has an in-degree entry
    for node in all_nodes:
        if node not in in_degree:
            in_degree[node] = 0

    # Compute in-degree for each node based on graph edges
    for node, prereqs in graph.items():
        for p in prereqs:
            in_degree[node] = in_degree.get(node, 0) + 1

    # Initialize queue with nodes having in-degree 0
    queue = deque(sorted([n for n in all_nodes if in_degree.get(n, 0) == 0]))
    result = []

    while queue:
        # Pop lexicographically smallest
        node = queue.popleft()
        result.append(node)

        # For each node that depends on this node, reduce its in-degree
        dependents = [n for n in all_nodes if node in graph.get(n, [])]
        for dep in dependents:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                queue.append(dep)
        queue = deque(sorted(queue))

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected in graph")

    return result
